DROP TABLE IF EXISTS "permiso_rol", "rol_usuario", "estado_usuario", "sesion", "usuario", "permiso", "rol", "estado" CASCADE;

CREATE TABLE "estado" (
  "id_estado" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "descripcion" TEXT NOT NULL
);

CREATE TABLE "rol" (
  "id_rol" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre_rol" TEXT NOT NULL UNIQUE
);

CREATE TABLE "permiso" (
  "id_permiso" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "descripcion" TEXT NOT NULL
);

CREATE TABLE "usuario" (
  "id_usuario" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombres" TEXT NOT NULL,
  "apellidos" TEXT NOT NULL,
  "tipo_documento" TEXT,
  "numero_identificacion" TEXT NOT NULL UNIQUE,
  "telefono" TEXT,
  "direccion" TEXT,
  "fecha_nacimiento" DATE,
  "correo_usuario" TEXT NOT NULL UNIQUE,
  "contraseña_usuario" TEXT NOT NULL,
  "acepta_terminos_condiciones" BOOLEAN NOT NULL DEFAULT false,
  "creado_en" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "sesion" (
  "id_sesion" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_usuario" INTEGER NOT NULL,
  "token_sesion" TEXT NOT NULL,
  "fecha_hora_sesion" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "sesion_id_usuario_fkey" FOREIGN KEY ("id_usuario")
    REFERENCES "usuario"("id_usuario") ON DELETE CASCADE
);

CREATE TABLE "estado_usuario" (
  "id_estado_usuario" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_usuario" INTEGER NOT NULL,
  "id_estado" INTEGER NOT NULL,
  "fecha_estado_usuario" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "estado_usuario_id_estado_fkey" FOREIGN KEY ("id_estado")
    REFERENCES "estado"("id_estado"),
  CONSTRAINT "estado_usuario_id_usuario_fkey" FOREIGN KEY ("id_usuario")
    REFERENCES "usuario"("id_usuario") ON DELETE CASCADE
);

CREATE TABLE "rol_usuario" (
  "id_rol_usuario" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_usuario" INTEGER NOT NULL,
  "id_rol" INTEGER NOT NULL,
  CONSTRAINT "rol_usuario_id_rol_fkey" FOREIGN KEY ("id_rol")
    REFERENCES "rol"("id_rol") ON DELETE CASCADE,
  CONSTRAINT "rol_usuario_id_usuario_fkey" FOREIGN KEY ("id_usuario")
    REFERENCES "usuario"("id_usuario") ON DELETE CASCADE,
  CONSTRAINT "rol_usuario_usuario_rol_key" UNIQUE ("id_usuario", "id_rol")
);

CREATE TABLE "permiso_rol" (
  "id_permiso_rol" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_rol" INTEGER NOT NULL,
  "id_permiso" INTEGER NOT NULL,
  CONSTRAINT "permiso_rol_id_permiso_fkey" FOREIGN KEY ("id_permiso")
    REFERENCES "permiso"("id_permiso") ON DELETE CASCADE,
  CONSTRAINT "permiso_rol_id_rol_fkey" FOREIGN KEY ("id_rol")
    REFERENCES "rol"("id_rol") ON DELETE CASCADE,
  CONSTRAINT "permiso_rol_rol_permiso_key" UNIQUE ("id_rol", "id_permiso")
);

INSERT INTO "rol" ("nombre_rol") VALUES
  ('ESTUDIANTE'), ('ADMIN'), ('DONANTE'), ('TALLERISTA'), ('ACUDIENTE');
